package com.turboio.addon;

import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.function.LongSupplier;

/** Read-only IOARAW01 source. No archive constructor/import, repair, credentials
 * in metadata, original-file writes or claim of whole-recording completeness. */
final class LifelogAudioRemoteSource extends LifelogAudioSource {
 private static final byte[] MAGIC={'I','O','A','R','A','W','0','1'};
 private final File file;private final Map<String,Object> metadata,receipt;private final AudioConfig config;private final LongSupplier clock;private final long rawBytes;
 private LifelogAudioRemoteSource(File file,Map<String,Object> metadata,Map<String,Object> receipt,AudioConfig config,LongSupplier clock)throws IOException{
  super(proof((String)metadata.get("material_id"),WireJson.map(metadata.get("context")),WireJson.map(metadata.get("archive")),(String)metadata.get("task_sha256"),number(metadata,"first_sequence")),WireJson.object("location","server","server_id",config.connection.server,"object_id",receipt.get("object_id"),"sha256",receipt.get("sha256"),"stored_at",receipt.get("stored_at"),"expires_at",receipt.get("expires_at"),"material_revision",receipt.get("material_revision"),"source_body_sha256",receipt.get("source_body_sha256")),true);
  this.file=file;this.metadata=WireJson.map(WireJson.copy(metadata));this.receipt=WireJson.map(WireJson.copy(receipt));this.config=config;this.clock=clock;rawBytes=number(WireJson.map(metadata.get("archive")),"raw_bytes");
 }
 private static void safe(File path,boolean directory)throws IOException{require(!Files.isSymbolicLink(path.toPath())&&path.getAbsoluteFile().equals(path.getCanonicalFile())&&(directory?path.isDirectory():path.isFile()),"AUDIO_REMOTE_PATH");if(!directory)try{Object links=Files.getAttribute(path.toPath(),"unix:nlink",LinkOption.NOFOLLOW_LINKS);require(links instanceof Number&&((Number)links).longValue()==1,"AUDIO_REMOTE_PATH");}catch(UnsupportedOperationException invalid){throw new IOException("AUDIO_REMOTE_PATH");}}
 private static Map<String,Object> header(DataInputStream in,String account,String material,long size)throws IOException{
  try{byte[] magic=new byte[8];in.readFully(magic);require(Arrays.equals(magic,MAGIC),"AUDIO_REMOTE_FORMAT");int length=in.readInt();long raw=in.readLong();require(length>0&&length<=65536&&raw>=8&&raw<=LifelogAudioArchive.MAX_BYTES&&20L+length+raw==size,"AUDIO_REMOTE_FORMAT");byte[] header=new byte[length];in.readFully(header);Map<String,Object> m=WireJson.map(WireJson.read(header,65536,5000));AudioUploadWire.keys(m,"format","context","first_sequence","archive","material_id","task_sha256","source_link_verified","recording_complete");
   Map<String,Object> c=WireJson.map(m.get("context"));AudioUploadWire.keys(c,"account","peer","generation","clock_epoch");Map<String,Object> state=LifelogAudioArchive.copiedState(m.get("archive")),owner=WireJson.map(state.get("owner"));require("turboio-lifelog-raw/1".equals(m.get("format"))&&account.equals(c.get("account"))&&material.equals(m.get("material_id"))&&Boolean.TRUE.equals(m.get("source_link_verified"))&&Boolean.FALSE.equals(m.get("recording_complete"))&&number(m,"first_sequence")>0&&number(state,"raw_bytes")==raw&&account.equals(owner.get("account"))&&Objects.equals(c.get("peer"),owner.get("peer"))&&Objects.equals(c.get("generation"),owner.get("generation")),"AUDIO_REMOTE_PROVENANCE");AudioUploadWire.hash(m.get("task_sha256"));require(c.get("clock_epoch") instanceof String&&((String)c.get("clock_epoch")).matches("[a-f0-9]{32}"),"AUDIO_REMOTE_PROVENANCE");return m;
  }catch(EOFException|IllegalArgumentException|ClassCastException invalid){throw new IOException("AUDIO_REMOTE_FORMAT");}
 }
 static LifelogAudioSource open(File cache,AudioConfig config,String material,AudioDownloads.Download download,LifelogAudioArchive.Guard guard,LongSupplier clock)throws IOException{
  guard.check();require(config!=null&&download!=null&&download.complete&&download.file!=null,"AUDIO_REMOTE_DOWNLOAD_INCOMPLETE");require(config.connection.expiresAt>clock.getAsLong(),"AUDIO_CREDENTIAL_EXPIRED");Map<String,Object> receipt=AudioDownloadWire.receipt(download.receipt,config.connection,material,clock.getAsLong(),true);require("raw".equals(receipt.get("kind")),"AUDIO_EXPORT_FORMAT_UNSUPPORTED");File base=cache.getCanonicalFile();require(!Files.isSymbolicLink(cache.toPath()),"AUDIO_REMOTE_PATH");File dir=base;safe(dir,true);for(String name:new String[]{"lifelog-audio-downloads",config.account,config.connection.binding(),(String)receipt.get("object_id")}){dir=new File(dir,name);safe(dir,true);}File file=new File(dir,"payload.bin");safe(file,false);require(file.equals(download.file.getAbsoluteFile())&&file.length()==AudioUploadWire.number(receipt.get("bytes")),"AUDIO_REMOTE_PATH");
  Map<String,Object> metadata;try(DataInputStream in=new DataInputStream(Files.newInputStream(file.toPath(),StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS))){metadata=header(in,config.account,material,file.length());}guard.check();return new LifelogAudioRemoteSource(file,metadata,receipt,config,clock);
 }
 @Override void current(LifelogAudioArchive.Guard guard)throws IOException{guard.check();require(config.connection.expiresAt>clock.getAsLong(),"AUDIO_CREDENTIAL_EXPIRED");require(AudioUploadWire.time(receipt.get("expires_at"))>clock.getAsLong(),"AUDIO_EXPIRED");}
 @Override protected void range(long first,long last)throws IOException{Map<String,Object> capture=WireJson.map(receipt.get("capture"));require(AudioUploadWire.time(capture.get("first_received_at"))==first&&AudioUploadWire.time(capture.get("last_received_at"))==last&&Boolean.FALSE.equals(capture.get("recording_complete")),"AUDIO_REMOTE_PROVENANCE");}
 @Override protected void read(LifelogAudioArchive.Visitor visitor,LifelogAudioArchive.Guard guard)throws IOException{
  current(guard);safe(file,false);long size=AudioUploadWire.number(receipt.get("bytes"));require(file.length()==size,"AUDIO_REMOTE_CHANGED");MessageDigest hash;try{hash=MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}
  try(DigestInputStream digest=new DigestInputStream(Files.newInputStream(file.toPath(),StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS),hash);DataInputStream in=new DataInputStream(digest)){
   Map<String,Object> fresh=header(in,account,material,size);require(Arrays.equals(WireJson.bytes(metadata),WireJson.bytes(fresh))&&number(WireJson.map(fresh.get("archive")),"raw_bytes")==rawBytes,"AUDIO_REMOTE_CHANGED");LifelogAudioArchive.visitCopied(in,fresh.get("archive"),visitor,()->current(guard));
   StringBuilder sha=new StringBuilder();for(byte b:hash.digest())sha.append(String.format(Locale.ROOT,"%02x",b&255));require(sha.toString().equals(receipt.get("sha256"))&&file.length()==size,"AUDIO_REMOTE_CHANGED");
  }current(guard);
 }
}
